			break;
		case ZRTP_KEYAGREEMENT_EC25	:
			pvLength = 64;
			break;
		case ZRTP_KEYAGREEMENT_EC38	:
			pvLength = 96;
			break;
		case ZRTP_KEYAGREEMENT_EC52 :
